urn k; } }; if (!history.length) return {}; var selfS = this; var scores = history.map(function(r) { return r.results ? r.results.score || 0 : 0; }); var totalScore = scores.reduce(function(s, p) { return s + p; }, 0); var avgScore = totalScore / scores.length; var avgR = Math.round(avgScore); var perfId = this._band(avgR); var performance = perfId; var insights = selfS._insights(history, scores, t); var low = 0; for (var li = 1; li < scores.length; li++) { if (scores[li] < scores[low]) low = li; } var turningPoint = (scores[low] >= 90) ? t('tp_none') : t('tp_round').split('{r}').join(low + 1).split('{s}').join(scores[low]) + ' ' + t('tp_why_r' + (low + 1)); return { totalScore: totalScore, avgScore: avgR, overallScore: avgR, score: avgR, performance: performance, performanceLabel: t('perf_' + perfId), performanceKey: 'perf_' + perfId, insights: insights, turningPoint: turningPoint, questions: [t('dq1'), t('dq2')] }; } _insights(history, scores, t) { /* one line per round, built only from what this run entered (no line describes a play the student did not make) */ var R = function(i) { return (history[i] && history[i].results) || {}; }; var near = function(x, v, tol) { return typeof x === 'number' && !isNaN(x) && Math.abs(x - v) <= tol; }; var out = []; var r1 = R(0), r2 = R(1), r3 = R(2), r4 = R(3); var l1 = []; if (r1.select1 === '30') l1.push(t('ins_r1_oldrate')); else if (r1.select1 === '25') l1.push(t('ins_r1_otherrate')); if (near(r1.input1, 4.2, 0.1)) l1.push(t('ins_r1_notax')); if (!l1.length) l1.push((scores[0] || 0) >= 90 ? t('ins_r1_good') : t('ins_r1_weak')); out.push(l1.join(' ')); if (history.length > 1) { var l2 = []; var adj = r2.input2; if (near(adj, 2.01, 0.1) || near(adj, 3.71, 0.1) || near(adj, 4.79, 0.1)) l2.push(t('ins_r2_double')); if (near(r2.input1, 60, 5)) l2.push(t('ins_r2_realizable')); if (near(adj, 0.99, 0.1)) l2.push(t('ins_r2_rateonly')); if (!l2.length) l2.push((scores[1] || 0) >= 90 ? t('ins_r2_good') : t('ins_r2_weak')); out.push(l2.join(' ')); } if (history.length > 2) { var st = r3.select1; out.push(st === 'A' ? t('ins_r3_A') : st === 'B' ? t('ins_r3_B') : t('ins_r3_CD')); } if (history.length > 3) { var tr = r4.select1; var n = Math.min(Math.max(Math.round(Number(r4.input1) || 0), 0), 4); out.push((tr === 'minimal' ? t('ins_r4_minimal') : tr === 'moderate' ? t('ins_r4_moderate') : t('ins_r4_full')) + ' ' + t('ins_r4_c' + n)); } return out; } _band(avg) { /* Excellent = no conceptual mistake: one costs at least 10 final points; bands from the P6/P4 sweep */ return avg >= 92 ? 'excellent' : avg >= 75 ? 'good' : avg >= 50 ? 'satisfactory' : 'needs'; } getHint(state, results) { if (!results) return null; if (results.score < 40) return window.mySimulation.t('hint_low_score'); if (results.score >= 80) return window.mySimulation.t('hint_high_score'); return null; } getHistoryTableConfig() { var selfH = this; return [ { key: 'results.period', label: 'Round', i18nKey: 'col_round' }, { key: 'results.input1', label: 'Input 1', i18nKey: 'col_input1', formatter: function(v) { return v !== undefined ? v.toFixed(1) : '-'; } }, { key: 'results.input2', label: 'Input 2', i18nKey: 'col_input2', formatter: function(v) { return v !== undefined ? v.toFixed(1) : '-'; } }, { key: 'results.select1', label: 'Selection', i18nKey: 'col_select', formatter: function(v) { var k = 'fb_transp_' + v; var tv = selfH._t(k); return (tv !== k) ? tv : v; } }, { key: 'results.score', label: 'Score', i18nKey: 'col_score', formatter: function(v) { return v + '/100'; } } ]; } getPresets() { return null; } getTranslations() { return { en: { chart_alt: 'Score by round, out of 100. The same values are in the history table above.', dq2: 'C and D both disclose before selling. What does the auditor certify in each, and when?', dq1: 'The reported US$5.8M at 30% implies about US$19.3M of differences; the working paper lists US$8.8M. What does Lemus ask Recinos before Tuesday?', complete_dq_label: 'For class discussion', complete_tp_label: 'Turning point:', tp_why_r4: 'The last message decided what the market, the bondholders and the family heard, and in what order.', tp_why_r3: 'The bond decision set the terms for everything you could disclose afterwards.', tp_why_r2: 'Equity, the figure the banks will put in the prospectus, did not follow from your own balances.', tp_why_r1: 'The balances were off from the start, and every later figure depends on them.', tp_round: 'Round {r} ({s}/100).', tp_none: 'no round fell below 90.', ins_r4_c4: 'You bought all four controls: the first two address the cause; the other two cost US$300K a year without covering it.', ins_r4_c3: 'The third control widens internal audit but would not have caught this rate.', ins_r4_c2: 'You chose the two controls that would have caught this error.', ins_r4_c1: 'An IFRS specialist helps, but without a quarterly review the error can recur.', ins_r4_c0: 'With no controls, nothing stops the error from happening again.', ins_r4_full: 'Round 4: you told the market first and every audience after it.', ins_r4_moderate: 'Round 4: you told only regulators and investors; in a listed company that is selective disclosure, and the market must hear first.', ins_r4_minimal: 'Round 4: you chose minimal disclosure; the restatement is refiled with the regulator and the exchange anyway, and bondholders will read it without context.', ins_r3_CD: 'Round 3: you disclosed before selling (C or D); what separates them is what the auditor certifies, and when.', ins_r3_B: 'Round 3: you delayed the bond and accepted the family\'s US$5–10M estimate as its price; did anyone test that figure?', ins_r3_A: 'Round 3: you went ahead with the bond without disclosing the restatement, on figures the auditor had objected to; the cost arrived in Round 4 as lost credibility.', ins_r2_weak: 'Round 2: the adjustment does not match the Round-1 balances; rebuild the liability change and the recognized asset separately.', ins_r2_good: 'Round 2: you carried the Round-1 balances into equity with a single recoverability test.', ins_r2_rateonly: 'You only re-measured the reported US$5.8M at the new rate; why keep it when the listed differences support US$2.52M?', ins_r2_realizable: 'You mixed up the realizable part (60%) with the part that is not recoverable (40%).', ins_r2_double: 'Round 2: you applied a double haircut to the deferred tax asset (60% realizable and then a 40% allowance); IAS 12.24 asks for one recoverability test.', ins_r1_good: 'Round 1: you classified the four items and measured both balances at the enacted rate.', ins_r1_notax: 'You entered the US$4.2M difference as if it were the tax: the asset is the difference times the rate, US$1.20M.', ins_r1_otherrate: 'Round 1: you used the 25% a colleague proposed, which no enacted rate supports; the confirmed rate was 28.6%.', ins_r1_oldrate: 'Round 1: you applied the old 30% rate of the local statements; IAS 12.47 asks for the enacted rate expected at reversal, 28.6%.', input_range: 'Enter a value between {min} and {max}.', fb_r4_carryA: 'Credibility: the bond was announced on figures the auditor had objected to, so this disclosure reads as a correction forced on the company (−20).', title: `El Impuesto Diferido`, subtitle: `Inmobiliaria Centroamérica S.A. — IFRS Transition Crisis`, round_label: `Round`, period_of: `of`, equity_label: `Reported Equity`, dta_label: `Deferred Tax Asset`, dtl_label: `Deferred Tax Liability`, score_label: 'Cumulative Score', briefing_heading: `Situation Briefing`, decisions_heading: `Your Decisions`, submit_btn: `Submit Round`, undo_btn: `Undo Last Round`, feedback_heading: `Round Feedback`, input1_label: `Input 1`, input2_label: `Input 2`, select1_label: `Selection`, input1_warning: `Please enter a valid number for the first input`, input2_warning: `Please enter a valid number for the second input`, select_warning: `Please make a selection`, hint_low_score: 'Look back at the working paper: which figure did you leave out, or use twice?', hint_high_score: `Excellent work! You demonstrated strong analytical skills this round.`, col_round: `Round`, col_input1: `Value 1`, col_input2: `Value 2`, col_select: `Selection`, col_score: `Score`, input1_placeholder: `Enter value`, input2_placeholder: `Enter value`, chart_title: `Score by Round`, chart_series: `Round Score`, perf_excellent: `Excellent`, perf_good: `Good`, perf_satisfactory: `Satisfactory`, perf_needs: `Needs Improvement`, ins_r1_strong: `Strong understanding of temporary differences and IAS 12 concepts.`, ins_r1_weak: 'Round 1: your balances do not follow from the working paper; classify each item (asset or liability side) before multiplying by the rate.', ins_r3_strong: `Good crisis management — balanced transparency with business needs.`, ins_r3_weak: `Consider that full disclosure during a restatement protects against future litigation risk.`, complete_title: `Restatement Complete`, complete_avg_label: `Average Accuracy`, complete_total_label: `Total Score`, complete_insights_label: `Key Takeaways`, r1_title: 'Round 1 — Identify Temporary Differences', r1_desc: '<strong>Inmobiliaria Centroamérica S.A. (InmCA)</strong> is moving from local GAAP to IFRS. The auditor, Halvorsen Ibarra, says the deferred taxes are miscalculated and misclassified.<br><br><strong>Your task:</strong> compute the total <strong>Deferred Tax Asset (DTA)</strong> and <strong>Deferred Tax Liability (DTL)</strong> from the working paper, in US$ millions, and choose the rate you applied.<br><br><strong>Working paper:</strong><br>• Construction project A: tax deduction already taken, book revenue still deferred; US$2.1M on the deferred-tax-asset side, never recorded<br>• Construction project B: same pattern; US$2.1M on the deferred-tax-asset side, never recorded<br>• Investment property B: cost US$20M, IFRS fair value US$24M; a US$4M gain on the deferred-tax-liability side<br>• Fixed assets: accelerated tax depreciation against straight-line book depreciation; a difference of about US$4.8M on the liability side<br>• Income tax rate the tax team confirmed for InmCA: 28.6% (the local-GAAP statements assumed 30%)<br>• Reported at the end of 2023: a DTL of US$5.8M computed at 30%; no DTA', r1_in1: 'Total DTA ($M)', r1_in2: 'Total DTL ($M)', r1_sel: 'Tax Rate Applied', r1_opt_28_6: '28.6% — the rate the tax team confirmed', r1_opt_30: '30% — the rate behind the local-GAAP statements', r1_opt_25: '25% — the figure a colleague proposed', r2_title: 'Round 2 — Restatement Impact on Equity', r2_desc: 'Carry your Round-1 balances into the 2023 balance sheet.<br><br><strong>Reported FY 2023 (local GAAP):</strong> Assets US$280M | Liabilities US$195M, including a DTL of US$5.8M computed at 30% | no DTA | Equity US$85M<br><br><strong>The auditor\'s judgment:</strong> InmCA needs future taxable profit to use the omitted DTA, and real estate is volatile. Halvorsen Ibarra considers only 60% of it realizable.<br><br><strong>Your task:</strong> enter the share of the DTA that is not recoverable (%), the net adjustment to equity (US$M, positive if equity rises) and choose the restated equity.', r2_in1: 'DTA not recoverable (%)', r2_in2: 'Net Equity Adjustment ($M)', r2_sel: 'Restated Equity ($M)', r2_opt_87: '$87M — equity rises $2M', r2_opt_85: '$85M — equity stays unchanged', r2_opt_83: '$83M — equity down $2M', r2_opt_89: '$89M — equity rises $4M', r3_title: 'Round 3 — Bond Issuance vs. Restatement Timeline', r3_desc: '<strong>The crisis:</strong> Halvorsen Ibarra requires a restatement (4-6 weeks). But InmCA planned a $80M bond issuance announcement for November 15.<br><br><strong>Timeline:</strong><br>• Oct 31: Halvorsen Ibarra completes audit, requires restatement<br>• Nov 5: Scheduled meeting with investment banks<br>• Nov 15: Planned bond announcement<br>• Nov 30: Q3 financials filing deadline<br>• Dec 15: Expected bond closing<br><br><strong>The Marroquín family (70% shareholder)</strong> demands proceeding with bonds — a 2-month delay could cost $5-10M in construction project losses.<br><br><strong>Choose your strategy:</strong><br>(A) Proceed with bond announcement as planned — risk regulatory action<br>(B) Delay bonds until restatement is complete — lose 6-8 weeks<br>(C) Announce restatement immediately, proceed with bonds using restated numbers — transparent but tight timeline<br>(D) Obtain comfort letter from Halvorsen Ibarra, proceed with disclosure — unusual but feasible<br><br>Also estimate the direct cost of your strategy (US$M) and how many weeks the restatement itself will take.', r3_in1: 'Estimated Cost Impact ($M)', r3_in2: 'Restatement Timeline (weeks)', r3_sel: 'Strategy Choice', r3_opt_a: '(A) Proceed as planned, no disclosure, as the family asks', r3_opt_b: '(B) Delay the bonds until the restatement is complete', r3_opt_c: '(C) Announce the restatement and proceed on restated numbers', r3_opt_d: '(D) Comfort letter from the auditor + disclosure', r4_title: 'Round 4 — Stakeholder Communication and Future Controls', r4_desc: 'InmCA must now communicate the restatement to all stakeholders and implement controls to prevent recurrence.<br><br><strong>Communication targets:</strong><br>• Marroquín family (majority shareholder) — private email<br>• Bond investors — prospectus disclosure section<br>• Investment banks — roadshow presentation<br>• Regulators and stock exchange — formal filing<br><br><strong>Key message elements:</strong> The adjustment is technical (not fraud), raises reported equity (Round 2), does not affect operations or cash, and is being audited by a Big 4 firm.<br><br><strong>Future controls to consider:</strong><br>1. Designate an IFRS specialist<br>2. Quarterly deferred tax review process<br>3. Expand internal audit team<br>4. Regular IFRS training for accounting staff<br><br><strong>Your task:</strong> Rate your disclosure transparency level and select how many of the controls to implement, taken in the order listed (each costs ~$150K/year).', r4_in1: 'Controls to implement, in list order (0-4)', r4_in2: 'Annual Controls Budget ($K)', r4_sel: 'Disclosure Transparency Level', r4_opt_full: 'Full transparency — proactive disclosure to all', r4_opt_moderate: 'Moderate — regulators and investors only, without public noise', r4_opt_minimal: 'Minimal — only the legal minimum for a technical error', fb_round_score: 'Round score', fb_r1_title: 'Round 1 Results:', fb_r1_dta: 'Asset: US$4.2M of deductible differences × 28.6% = US$1.20M (you entered: {v})', fb_r1_dtl: 'Liability: US$4.0M + US$4.8M = US$8.8M of taxable differences × 28.6% = US$2.52M (you entered: {v})', fb_r1_rate: 'Rate: 28.6%, the enacted rate expected when the differences reverse, IAS 12.47 (you selected: {v})', fb_r1_note: 'Check the reconciliation: the reported US$5.8M at 30% implies about US$19.3M of taxable differences, against US$8.8M listed. Before Tuesday, a CFO asks the auditor for the full schedule.', fb_r2_title: 'Round 2 Results:', fb_r2_allow: 'Not recoverable: 40%, since the auditor judges 60% realizable (you entered: {v})', fb_r2_adj: 'Net adjustment: liability from US$5.8M to US$2.52M (+US$3.28M) plus 60% of the US$1.20M asset (+US$0.72M) = +US$4.00M (you entered: {v})', fb_r2_eq: 'Restated equity: US$85M + US$4.0M = US$89M (you selected: {v})', fb_r2_note: 'Under IAS 12.24 recoverability is one test: recognize the probable 60%. Taking 60% and then a further 40% allowance applies the same doubt twice. The correction is about 4.7% of equity and it raises equity: small in amount, not small in a bond prospectus.', fb_r3_title: 'Round 3 Results:', fb_r3_strategy: 'Strategy selected: {v}', fb_r3_best: 'C and D both disclose before the bond is sold; they differ on what the auditor certifies and when. The restatement takes four to six weeks whatever you choose, and neither C nor D carries a stated direct cost.', fb_r3_alt: 'B gives up six to eight weeks and carries the family\'s US$5–10M estimate, a figure worth testing. A sells bonds on figures the auditor has already objected to.', fb_r4_title: 'Round 4 Results:', fb_r4_transp: 'Transparency: {v}', fb_transp_full: 'full', fb_transp_moderate: 'moderate', fb_transp_minimal: 'minimal', fb_r4_controls: 'Controls implemented: {v} of 4', fb_r4_budget: 'Annual budget: {v}', fb_r4_note: 'A listed company tells the market first: the formal filing, then investors and banks, then the family. Of the four controls, the first two (an IFRS specialist and a quarterly deferred-tax review) would have caught a 30% rate where 28.6% applied, at about US$150K each.' }, es: { chart_alt: 'Puntaje por ronda, sobre 100. Los mismos valores están en la tabla de historial.', dq2: 'C y D revelan antes de vender. ¿Qué certifica el auditor en cada una, y cuándo?', dq1: 'Los US$5.8M reportados al 30 % implican unos US$19.3M de diferencias; el papel de trabajo lista US$8.8M. ¿Qué le pide Lemus a Recinos antes del martes?', complete_dq_label: 'Para la discusión en clase', complete_tp_label: 'Punto de quiebre:', tp_why_r4: 'El último mensaje decidió qué oyeron el mercado, los tenedores de bonos y la familia, y en qué orden.', tp_why_r3: 'La decisión sobre los bonos fijó las condiciones de todo lo que pudo comunicar después.', tp_why_r2: 'El patrimonio, la cifra que los bancos pondrán en el prospecto, no se siguió de sus propios saldos.', tp_why_r1: 'Los saldos salieron mal desde el principio, y todas las cifras posteriores dependen de ellos.', tp_round: 'Ronda {r} ({s}/100).', tp_none: 'ninguna ronda bajó de 90.', ins_r4_c4: 'Compró los cuatro controles: los dos primeros atacan la causa; los otros dos cuestan US$300K al año sin cubrirla.', ins_r4_c3: 'El tercer control amplía la auditoría interna, pero no habría detectado esta tasa.', ins_r4_c2: 'Eligió los dos controles que habrían detectado este error.', ins_r4_c1: 'Un especialista en NIIF ayuda, pero sin una revisión trimestral el error puede repetirse.', ins_r4_c0: 'Sin controles, nada impide que el error se repita.', ins_r4_full: 'Ronda 4: informó primero al mercado y después a cada público.', ins_r4_moderate: 'Ronda 4: informó solo a reguladores e inversionistas; en una empresa cotizada eso es divulgación selectiva, y el mercado debe enterarse primero.', ins_r4_minimal: 'Ronda 4: eligió la divulgación mínima; la reexpresión se presenta igual ante el regulador y la bolsa, y los tenedores de bonos la leerán sin contexto.', ins_r3_CD: 'Ronda 3: reveló antes de vender (C o D); lo que las separa es qué certifica el auditor, y cuándo.', ins_r3_B: 'Ronda 3: aplazó los bonos y aceptó como precio la estimación de US$5–10M de la familia; ¿alguien puso a prueba esa cifra?', ins_r3_A: 'Ronda 3: siguió con los bonos sin divulgar la reexpresión, sobre cifras que el auditor ya había objetado; el costo llegó en la Ronda 4 como pérdida de credibilidad.', ins_r2_weak: 'Ronda 2: el ajuste no cuadra con los saldos de la Ronda 1; reconstruya por separado el cambio del pasivo y el activo reconocido.', ins_r2_good: 'Ronda 2: llevó los saldos de la Ronda 1 al patrimonio con una sola prueba de recuperabilidad.', ins_r2_rateonly: 'Solo re-midió los US$5.8M reportados a la nueva tasa; ¿por qué conservarlos si las diferencias listadas sostienen US$2.52M?', ins_r2_realizable: 'Confundió la parte realizable (60 %) con la parte no recuperable (40 %).', ins_r2_double: 'Ronda 2: aplicó un doble ajuste al activo diferido (60 % realizable y además 40 % de estimación); la NIC 12.24 pide una sola prueba de recuperabilidad.', ins_r1_good: 'Ronda 1: clasificó las cuatro partidas y midió ambos saldos a la tasa vigente.', ins_r1_notax: 'Ingresó la diferencia de US$4.2M como si fuera el impuesto: el activo es la diferencia por la tasa, US$1.20M.', ins_r1_otherrate: 'Ronda 1: usó el 25 % que propuso alguien del equipo, sin respaldo en una tasa vigente; la tasa confirmada era 28.6 %.', ins_r1_oldrate: 'Ronda 1: aplicó la tasa antigua del 30 % de los estados locales; la NIC 12.47 pide la tasa vigente esperada al revertirse, 28.6 %.', input_range: 'Ingrese un valor entre {min} y {max}.', fb_r4_carryA: 'Credibilidad: los bonos se anunciaron sobre cifras que el auditor había objetado, así que esta comunicación se lee como una corrección forzada (−20).', title: `El Impuesto Diferido`, subtitle: `Inmobiliaria Centroamérica S.A. — Crisis de Transición IFRS`, round_label: `Ronda`, period_of: `de`, equity_label: 'Patrimonio reportado', dta_label: 'Activo por impuesto diferido', dtl_label: 'Pasivo por impuesto diferido', score_label: 'Puntaje acumulado', briefing_heading: 'Situación de la ronda', decisions_heading: 'Sus decisiones', submit_btn: 'Enviar ronda', undo_btn: 'Deshacer última ronda', feedback_heading: 'Resultado de la ronda', input1_label: `Entrada 1`, input2_label: `Entrada 2`, select1_label: `Selección`, input1_warning: `Por favor ingrese un número válido para la primera entrada`, input2_warning: `Por favor ingrese un número válido para la segunda entrada`, select_warning: `Por favor haga una selección`, hint_low_score: 'Vuelva al papel de trabajo: ¿qué cifra dejó fuera o usó dos veces?', hint_high_score: '¡Excelente trabajo! Demostró un análisis sólido en esta ronda.', col_round: `Ronda`, col_input1: `Valor 1`, col_input2: `Valor 2`, col_select: `Selección`, col_score: `Puntaje`, input1_placeholder: `Ingrese valor`, input2_placeholder: `Ingrese valor`, chart_title: `Puntaje por Ronda`, chart_series: `Puntaje de Ronda`, perf_excellent: `Excelente`, perf_good: `Bueno`, perf_satisfactory: `Satisfactorio`, perf_needs: `Necesita Mejorar`, ins_r1_strong: `Sólido dominio de las diferencias temporales y los conceptos de IAS 12.`, ins_r1_weak: 'Ronda 1: sus saldos no salen del papel de trabajo; clasifique cada partida (lado del activo o del pasivo) antes de multiplicar por la tasa.', ins_r3_strong: `Buena gestión de crisis — equilibró transparencia con las necesidades del negocio.`, ins_r3_weak: `Considere que la divulgación completa durante un restatement protege contra el riesgo de litigio futuro.`, complete_title: 'Reexpresión completada', complete_avg_label: `Precisión Promedio`, complete_total_label: `Puntaje Total`, complete_insights_label: `Conclusiones Clave`, r1_title: 'Ronda 1 — Identificar Diferencias Temporales', r1_desc: '<strong>Inmobiliaria Centroamérica S.A. (InmCA)</strong> pasa de la norma contable local a las NIIF. El auditor, Halvorsen Ibarra, señala que los impuestos diferidos están mal calculados y mal clasificados.<br><br><strong>Su tarea:</strong> calcule el total del <strong>activo por impuesto diferido (DTA)</strong> y del <strong>pasivo por impuesto diferido (DTL)</strong> a partir del papel de trabajo, en millones de US$, y elija la tasa que aplicó.<br><br><strong>Papel de trabajo:</strong><br>• Proyecto de construcción A: deducción fiscal ya tomada, ingreso contable todavía diferido; US$2.1 millones del lado del activo diferido, no registrados<br>• Proyecto de construcción B: el mismo patrón; US$2.1 millones del lado del activo diferido, no registrados<br>• Propiedad de inversión B: costo US$20 millones, valor razonable NIIF US$24 millones; una ganancia de US$4 millones del lado del pasivo diferido<br>• Activos fijos: depreciación fiscal acelerada frente a línea recta contable; una diferencia de unos US$4.8 millones del lado del pasivo<br>• Tasa del impuesto sobre la renta confirmada por el equipo fiscal: 28.6 % (los estados bajo la norma local supusieron 30 %)<br>• Reportado al cierre de 2023: un DTL de US$5.8 millones calculado al 30 %; ningún DTA', r1_in1: 'DTA Total ($M)', r1_in2: 'DTL Total ($M)', r1_sel: 'Tasa Impositiva Aplicada', r1_opt_28_6: '28.6% — la tasa que confirmó el equipo fiscal', r1_opt_30: '30% — la tasa de los estados bajo la norma local', r1_opt_25: '25% — la propuesta de alguien del equipo', r2_title: 'Ronda 2 — Impacto de la reexpresión en el patrimonio', r2_desc: 'Lleve los saldos de la Ronda 1 al balance de 2023.<br><br><strong>Reportado al cierre de 2023 (norma local):</strong> Activos US$280M | Pasivos US$195M, incluido un DTL de US$5.8M calculado al 30 % | ningún DTA | Patrimonio US$85M<br><br><strong>El juicio del auditor:</strong> InmCA necesita utilidades fiscales futuras para usar el DTA omitido, y el negocio inmobiliario es volátil. Halvorsen Ibarra considera realizable solo el 60 %.<br><br><strong>Su tarea:</strong> ingrese la parte del DTA que no es recuperable (%), el ajuste neto al patrimonio (US$M, positivo si el patrimonio sube) y elija el patrimonio reexpresado.', r2_in1: 'DTA no recuperable (%)', r2_in2: 'Ajuste neto al patrimonio (US$M)', r2_sel: 'Patrimonio reexpresado (US$M)', r2_opt_87: '$87M — el patrimonio sube $2M', r2_opt_85: '$85M — el patrimonio no cambia', r2_opt_83: '$83M — el patrimonio cae $2M', r2_opt_89: '$89M — el patrimonio sube $4M', r3_title: 'Ronda 3 — Emisión de Bonos vs. Cronograma de Restatement', r3_desc: '<strong>La crisis:</strong> Halvorsen Ibarra requiere un restatement (4-6 semanas). Pero InmCA planeaba anunciar una emisión de bonos de $80M para el 15 de noviembre.<br><br><strong>Cronograma:</strong><br>• Oct 31: Halvorsen Ibarra completa auditoría, requiere restatement<br>• Nov 5: Reunión programada con bancos de inversión<br>• Nov 15: Anuncio planeado de bonos<br>• Nov 30: Fecha límite de filing de financieros Q3<br>• Dic 15: Cierre esperado de bonos<br><br><strong>La familia Marroquín (accionista 70%)</strong> exige proceder con los bonos — un retraso de 2 meses podría costar $5-10M en pérdidas de proyectos de construcción.<br><br><strong>Elija su estrategia:</strong><br>(A) Proceder con anuncio de bonos como planeado — riesgo regulatorio<br>(B) Retrasar bonos hasta completar restatement — perder 6-8 semanas<br>(C) Anunciar restatement inmediatamente, proceder con bonos bajo números restated — transparente pero ajustado<br>(D) Obtener carta de confort de Halvorsen Ibarra, proceder con disclosure — inusual pero factible<br><br>Estime también el costo directo de su estrategia (US$M) y cuántas semanas tomará la reexpresión.', r3_in1: 'Impacto Estimado en Costos ($M)', r3_in2: 'Cronograma de Restatement (semanas)', r3_sel: 'Elección de Estrategia', r3_opt_a: '(A) Seguir el plan sin disclosure, como pide la familia', r3_opt_b: '(B) Retrasar los bonos hasta cerrar el restatement', r3_opt_c: '(C) Anunciar el restatement y seguir con los números restated', r3_opt_d: '(D) Carta de confort del auditor + disclosure', r4_title: 'Ronda 4 — Comunicación a Stakeholders y Controles Futuros', r4_desc: 'InmCA debe ahora comunicar el restatement a todos los stakeholders e implementar controles para prevenir recurrencias.<br><br><strong>Objetivos de comunicación:</strong><br>• Familia Marroquín (accionista mayoritario) — email privado<br>• Inversionistas de bonos — sección de disclosure del prospecto<br>• Bancos de inversión — presentación del roadshow<br>• Reguladores y bolsa de valores — filing formal<br><br><strong>Elementos clave del mensaje:</strong> El ajuste es técnico (no fraude), aumenta el patrimonio reportado (Ronda 2), no afecta las operaciones ni la caja, y está siendo auditado por firma Big 4.<br><br><strong>Controles futuros a considerar:</strong><br>1. Designar especialista IFRS<br>2. Proceso trimestral de revisión de impuestos diferidos<br>3. Expandir equipo de auditoría interna<br>4. Capacitación regular en IFRS para personal contable<br><br><strong>Su tarea:</strong> Califique su nivel de transparencia en disclosure y seleccione cuántos de los controles implementar, en el orden de la lista (cada uno cuesta ~$150K/año).', r4_in1: 'Controles a implementar, en el orden de la lista (0-4)', r4_in2: 'Presupuesto Anual de Controles ($K)', r4_sel: 'Nivel de Transparencia de Disclosure', r4_opt_full: 'Transparencia total — disclosure proactivo a todos', r4_opt_moderate: 'Moderado — solo reguladores e inversionistas, sin ruido público', r4_opt_minimal: 'Mínimo — solo lo que exige la ley ante un error técnico', fb_round_score: 'Puntaje de esta ronda', fb_r1_title: 'Resultados de la Ronda 1:', fb_r1_dta: 'Activo: US$4.2M de diferencias deducibles × 28.6 % = US$1.20M (usted ingresó: {v})', fb_r1_dtl: 'Pasivo: US$4.0M + US$4.8M = US$8.8M de diferencias imponibles × 28.6 % = US$2.52M (usted ingresó: {v})', fb_r1_rate: 'Tasa: 28.6 %, la tasa vigente esperada cuando las diferencias se reviertan, NIC 12.47 (usted seleccionó: {v})', fb_r1_note: 'Revise la conciliación: los US$5.8M reportados al 30 % implican unos US$19.3M de diferencias imponibles, frente a US$8.8M listados. Antes del martes, una directora financiera pide al auditor el detalle completo.', fb_r2_title: 'Resultados de la Ronda 2:', fb_r2_allow: 'No recuperable: 40 %, porque el auditor considera realizable el 60 % (usted ingresó: {v})', fb_r2_adj: 'Ajuste neto: pasivo de US$5.8M a US$2.52M (+US$3.28M) más el 60 % del activo de US$1.20M (+US$0.72M) = +US$4.00M (usted ingresó: {v})', fb_r2_eq: 'Patrimonio reexpresado: US$85M + US$4.0M = US$89M (usted seleccionó: {v})', fb_r2_note: 'Según la NIC 12.24 la recuperabilidad es una sola prueba: se reconoce el 60 % probable. Tomar el 60 % y además una estimación del 40 % aplica dos veces la misma duda. La corrección es cerca del 4.7 % del patrimonio y lo aumenta: pequeña en monto, no en un prospecto de bonos.', fb_r3_title: 'Resultados de la Ronda 3:', fb_r3_strategy: 'Estrategia seleccionada: {v}', fb_r3_best: 'C y D revelan antes de vender los bonos; difieren en qué certifica el auditor y cuándo. La reexpresión toma de cuatro a seis semanas elija lo que elija, y ni C ni D tienen un costo directo declarado.', fb_r3_alt: 'B renuncia a seis u ocho semanas y carga la estimación de US$5–10M de la familia, una cifra que conviene poner a prueba. A vende bonos sobre cifras que el auditor ya objetó.', fb_r4_title: 'Resultados de la Ronda 4:', fb_r4_transp: 'Transparencia: {v}', fb_transp_full: 'total', fb_transp_moderate: 'moderada', fb_transp_minimal: 'mínima', fb_r4_controls: 'Controles implementados: {v} de 4', fb_r4_budget: 'Presupuesto anual: {v}', fb_r4_note: 'Una empresa cotizada informa primero al mercado: la presentación formal, luego inversionistas y bancos, y después la familia. De los cuatro controles, los dos primeros (un especialista en NIIF y una revisión trimestral de impuestos diferidos) habrían detectado una tasa del 30 % donde correspondía 28.6 %; cuestan unos US$150K cada uno.' } }; } } document.addEventListener('DOMContentLoaded', function() { window.mySimulation = new USF.SimulationFramework(); window.mySimulation.initialize(new DeferredTaxAdapter(), { simulationType: 'deferred_tax_486', maxPeriods: 4, autoSaveInterval: 30000 }); }); })();
